def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, 20.0))

    slots = int(max(1, supply // WATER_REQ))
    opp_infos = []
    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        prev_bid = prev.get('bid')
        if prev_bid is None:
            prev_bid = 0.0
        opp_infos.append({
            'id': oid,
            'bid': float(prev_bid),
            'hp': opp.get('hp', 10),
            'budget': opp.get('budget', 0.0),
            'need': opp.get('no_water_days', 0),
            'req': opp.get('water_requirement', WATER_REQ)
        })

    high_cindy = False
    david_bid = 0.0
    max_prev = 0.0
    urgent_opp = 0
    for info in opp_infos:
        if info['id'] == 'Cindy' and info['bid'] >= 130:
            high_cindy = True
        if info['id'] == 'David':
            david_bid = info['bid']
        if info['bid'] > max_prev:
            max_prev = info['bid']
        if info['hp'] <= 3 or info['need'] >= 2:
            urgent_opp += 1

    my_urgent = hp <= 3 or no_water >= 2
    very_urgent = hp <= 2 or no_water >= 3
    tight = slots <= 1

    target = 0.0

    if very_urgent:
        if high_cindy:
            target = 146.0
        else:
            target = max(92.0, max_prev + 3.0)
    elif my_urgent:
        if tight:
            if high_cindy:
                target = 118.0
            else:
                target = max(80.0, david_bid + 2.5, max_prev + 1.5)
        else:
            target = max(62.0, david_bid + 2.0)
    else:
        if tight:
            if high_cindy:
                target = max(36.0, min(58.0, david_bid + 1.5))
            else:
                target = max(48.0, david_bid + 2.0)
        else:
            if urgent_opp >= 2:
                target = 34.0
            else:
                target = 26.0

    if day >= 8 and hp >= 5 and not my_urgent:
        target *= 0.9
    if day >= 9 and my_urgent:
        target *= 1.15

    safe_cap = budget
    if not my_urgent:
        reserve_days = max(0, 10 - int(day))
        reserve = reserve_days * 10.0
        safe_cap = max(0.0, budget - reserve)
        if safe_cap <= 0:
            safe_cap = min(budget, 25.0)

    bid = min(target, budget, safe_cap if safe_cap > 0 else budget)
    if my_urgent:
        bid = min(target, budget)

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for agent_id, st in opponents_status.items():
        if st.get('alive', False):
            alive.append((agent_id, st))

    if not alive:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace for immediate reaction.
    cindy_trace = None
    max_prev_bid = -1.0
    prev_bids = []
    for agent_id, st in alive:
        prev = st.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                bid_val = float(bid)
            except Exception:
                continue
            prev_bids.append(bid_val)
            if bid_val > max_prev_bid:
                max_prev_bid = bid_val
            if agent_id == 'Cindy':
                cindy_trace = bid_val

    # Supply pressure estimate: higher supply reduces need to overbid.
    # Use a simple normalized factor.
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Base bid: aim to be competitive but not waste budget.
    # If supply is low (near 15), bid more; if high (near 25), bid less.
    base = DAILY_SALARY * (0.62 - 0.18 * supply_norm)

    # If Cindy was high yesterday, we anticipate continued pressure.
    cindy_high = False
    if cindy_trace is not None and cindy_trace >= DAILY_SALARY * 0.85:
        cindy_high = True

    # HP-aware escalation.
    # If my HP is low or I've had no water days, I must secure water.
    low_hp = my_hp <= 3.0
    urgent = low_hp or my_no_water_days >= 2

    # If yesterday there was a very high bid, slightly follow to avoid losing.
    if max_prev_bid >= DAILY_SALARY * 1.45:
        base = DAILY_SALARY * (0.75 - 0.12 * supply_norm)

    if urgent:
        target = DAILY_SALARY * (0.95 - 0.10 * supply_norm)
    elif cindy_high:
        target = base + DAILY_SALARY * 0.18
    else:
        target = base

    # Cap by budget and keep within reasonable bounds.
    target = max(0.0, min(my_budget, target))

    # If budget is too low, bid what we can.
    if my_budget <= 1e-6:
        return 0.0

    return float(target)

def get_bid(day_context, my_status, opponents_status):
